<?php require __DIR__.'/includes/header.php';requireAdmin();$rows=db()->query('SELECT c.*,COUNT(w.id) workers FROM companies c LEFT JOIN workers w ON w.company_id=c.id GROUP BY c.id ORDER BY c.id DESC')->fetchAll();?><h1><?=t('companies')?></h1><section class="card table-wrap"><table><thead><tr><th>Code</th><th><?=t('name_ar')?></th><th><?=t('name_en')?></th><th><?=t('workers')?></th><th><?=t('actions')?></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['company_code'])?></td><td><?=e($r['name_ar'])?></td><td><?=e($r['name_en'])?></td><td><?=$r['workers']?></td><td><a class="btn small" href="company-profile.php?company_id=<?=$r['id']?>">👁</a></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
